fmi2Real getReal(ModelInstance* comp, const fmi2ValueReference vr) {
  if (vr < 875) {
    return comp->fmuData->localData[0]->realVars[vr];
  }
  if (vr < 1057) {
    return comp->fmuData->simulationInfo->realParameter[vr-875];
  }
  if (vr < 1278) {
    int ix = realAliasIndexes[vr-1057];
    return ix>=0 ? getReal(comp, ix) : -getReal(comp, -(ix+1));
  }
  return NAN;
}

fmi2Status setReal(ModelInstance* comp, const fmi2ValueReference vr, const fmi2Real value) {
  // set start value attribute for all variable that has start value, till initialization mode
  if (vr < 875 && (comp->state == model_state_instantiated || comp->state == model_state_initialization_mode)) {
    put_real_element(value, 0, &comp->fmuData->modelData->realVarsData[vr].attribute.start);
  }
  if (vr < 875) {
    comp->fmuData->localData[0]->realVars[vr] = value;
    return fmi2OK;
  }
  if (vr < 1057) {
    comp->fmuData->simulationInfo->realParameter[vr-875] = value;
    return fmi2OK;
  }
  if (vr < 1278) {
    int ix = realAliasIndexes[vr-1057];
    return ix >= 0 ? setReal(comp, ix, value) : setReal(comp, -(ix+1), -value);
  }
  return fmi2Error;
}

static const int intAliasIndexes[15] = {
  4, 5, 6, 4, 5, 6, 4, 5, 6, 4, 5, 6, 4, 5, 6
};

fmi2Integer getInteger(ModelInstance* comp, const fmi2ValueReference vr) {
  if (vr < 16) {
    return comp->fmuData->localData[0]->integerVars[vr];
  }
  if (vr < 25) {
    return comp->fmuData->simulationInfo->integerParameter[vr-16];
  }
  if (vr < 40) {
    int ix = intAliasIndexes[vr-25];
    return ix>=0 ? getInteger(comp, ix) : -getInteger(comp, -(ix+1));
  }
  return 0;
}

fmi2Status setInteger(ModelInstance* comp, const fmi2ValueReference vr, const fmi2Integer value) {
  // set start value attribute for all variable that has start value, till initialization mode
  if (vr < 16 && (comp->state == model_state_instantiated || comp->state == model_state_initialization_mode)) {
    comp->fmuData->modelData->integerVarsData[vr].attribute.start = value;
  }
  if (vr < 16) {
    comp->fmuData->localData[0]->integerVars[vr] = value;
    return fmi2OK;
  }
  if (vr < 25) {
    comp->fmuData->simulationInfo->integerParameter[vr-16] = value;
    return fmi2OK;
  }
  if (vr < 40) {
    int ix = intAliasIndexes[vr-25];
    return ix >= 0 ? setInteger(comp, ix, value) : setInteger(comp, -(ix+1), -value);
  }
  return fmi2Error;
}
